def get_leaf_costs(part):
    mults = [m for p, c, m in rules if p == part]
    if not mults:
        return {part: 1}
    res = {}
    for c, m in [(c, m) for p, c, m in rules if p == part]:
        sub = get_leaf_costs(c)
        for leaf, count in sub.items():
            res[leaf] = res.get(leaf, 0) + count * m
    return res

crate_parts = get_leaf_costs('Crate')
beacon_parts = get_leaf_costs('Beacon')
crate_cost = sum(crate_parts[l] * costs[l] for l in crate_parts)
