result = round(crate_cost - beacon_cost, 2)

rules_rows = data_rows('Rules', {'B': 'string', 'C': 'string', 'D': 'number'})
rules = [cells('Rules', f'B{r}:D{r}') for r in rules_rows]
costs_rows = data_rows('Leaf costs', {'E': 'string', 'F': 'number'})
costs = {cells('Leaf costs', f'E{r}'): num('Leaf costs', f'F{r}') for r in costs_rows}

def get_leaf_costs(item, mult=1):
    children = [r for r in rules if r[0] == item]
    if not children:
        return {item: costs.get(item, 0) * mult}
    res = {}
    for p, c, m in children:
        sub = get_leaf_costs(c, mult * m)
        for k, v in sub.items():
            res[k] = res.get(k, 0) + v
    return res

crate_costs = get_leaf_costs('Crate')
beacon_costs = get_leaf_costs('Beacon')
